package br.com.pacto.recrutamento.infra.templatevaga;
import javax.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="templates_vaga") public class TemplateVagaJpaEntity { @Id private UUID id; @Column(name="responsavel_id",nullable=false) private UUID responsavelId; @Column(nullable=false,length=150) private String titulo; @Column(nullable=false,columnDefinition="TEXT") private String descricao; @Column(name="criado_em",nullable=false) private OffsetDateTime criadoEm; @Column(name="atualizado_em",nullable=false) private OffsetDateTime atualizadoEm; @Column(name="excluido_em") private OffsetDateTime excluidoEm; protected TemplateVagaJpaEntity(){} TemplateVagaJpaEntity(UUID id,UUID r,String t,String d,OffsetDateTime c,OffsetDateTime a,OffsetDateTime e){this.id=id;responsavelId=r;titulo=t;descricao=d;criadoEm=c;atualizadoEm=a;excluidoEm=e;} @PrePersist void incluir(){OffsetDateTime n=OffsetDateTime.now();if(criadoEm==null)criadoEm=n;atualizadoEm=n;} @PreUpdate void atualizar(){atualizadoEm=OffsetDateTime.now();} UUID getId(){return id;} UUID getResponsavelId(){return responsavelId;} String getTitulo(){return titulo;} String getDescricao(){return descricao;} OffsetDateTime getCriadoEm(){return criadoEm;} OffsetDateTime getAtualizadoEm(){return atualizadoEm;} OffsetDateTime getExcluidoEm(){return excluidoEm;} }
